// ═══ CountDownLatch — one-time, different counters/waiters ═══
CountDownLatch latch = new CountDownLatch(3);

// Three DIFFERENT threads count down:
pool.submit(() -> { generateReport("accounting"); latch.countDown(); });
pool.submit(() -> { generateReport("loans"); latch.countDown(); });
pool.submit(() -> { generateReport("compliance"); latch.countDown(); });

// DIFFERENT thread waits:
latch.await();  // blocks until count = 0
mergeReports(); // all 3 reports ready!
// latch.await() again → returns IMMEDIATELY (count already 0)
// Cannot reset! Need new CountDownLatch for tomorrow.

// ═══ CyclicBarrier — reusable, same threads sync ═══
CyclicBarrier barrier = new CyclicBarrier(3, () -> {
    System.out.println("All 3 reached checkpoint! Proceeding...");
});

// THREE threads — each reaches barrier, ALL proceed together:
for (int i = 0; i < 3; i++) {
    pool.submit(() -> {
        phase1Work();
        barrier.await();  // waits for other 2 threads!
        // All 3 here now! Barrier auto-resets!
        phase2Work();
        barrier.await();  // waits for other 2 again!
        // Barrier reused for phase 2!
        phase3Work();
    });
}

// ═══ COMPARISON ═══
// Feature           CountDownLatch          CyclicBarrier
// Reusable?         NO (one-time)           YES (auto-resets)
// Who counts/waits? Different threads        Same threads
// Reset?            Cannot                  Automatic after each trip
// Barrier action?   NO                      YES (Runnable on trip)
// Use case          "Wait for N events"     "N threads sync at point"
// Broken?           N/A                     BrokenBarrierException
