// ─── File: src/test/java/com/bank/sync/BarrierVsLatchTest.java ───
package com.bank.sync;

import org.junit.jupiter.api.Test;
import java.util.concurrent.*;
import java.util.concurrent.atomic.*;
import static org.assertj.core.api.Assertions.*;

class BarrierVsLatchTest {

    // ═══ CountDownLatch: one-time, different counters/waiters ═══
    @Test
    void countDownLatch_oneTime() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(3);
        AtomicInteger reports = new AtomicInteger(0);
        ExecutorService pool = Executors.newFixedThreadPool(3);

        for (int i = 0; i < 3; i++) {
            pool.submit(() -> {
                reports.incrementAndGet();
                latch.countDown();
            });
        }

        latch.await(5, TimeUnit.SECONDS);
        assertThat(reports.get()).isEqualTo(3);

        // Cannot reuse!
        assertThat(latch.getCount()).isEqualTo(0);
        latch.await();  // returns IMMEDIATELY (already 0)

        pool.shutdown();
    }

    // ═══ CyclicBarrier: reusable, same threads sync ═══
    @Test
    void cyclicBarrier_reusablePhases() throws InterruptedException {
        int threads = 3;
        AtomicInteger phase1Count = new AtomicInteger(0);
        AtomicInteger phase2Count = new AtomicInteger(0);
        CyclicBarrier barrier = new CyclicBarrier(threads);
        CountDownLatch allDone = new CountDownLatch(threads);
        ExecutorService pool = Executors.newFixedThreadPool(threads);

        for (int i = 0; i < threads; i++) {
            pool.submit(() -> {
                try {
                    // Phase 1:
                    phase1Count.incrementAndGet();
                    barrier.await();  // sync! All 3 must reach here!
                    assertThat(phase1Count.get()).isEqualTo(3);  // guaranteed!

                    // Phase 2 (barrier auto-reset!):
                    phase2Count.incrementAndGet();
                    barrier.await();  // sync again! Reused!
                    assertThat(phase2Count.get()).isEqualTo(3);
                } catch (Exception e) { }
                allDone.countDown();
            });
        }

        allDone.await(5, TimeUnit.SECONDS);
        assertThat(phase1Count.get()).isEqualTo(3);
        assertThat(phase2Count.get()).isEqualTo(3);
        pool.shutdown();
    }

    // ═══ CyclicBarrier with barrier action ═══
    @Test
    void cyclicBarrier_withAction() throws InterruptedException {
        AtomicInteger actionRun = new AtomicInteger(0);
        CyclicBarrier barrier = new CyclicBarrier(2, () -> actionRun.incrementAndGet());
        CountDownLatch done = new CountDownLatch(2);

        for (int i = 0; i < 2; i++) {
            new Thread(() -> {
                try {
                    barrier.await();  // trip 1 → action runs!
                    barrier.await();  // trip 2 → action runs again!
                } catch (Exception e) { }
                done.countDown();
            }).start();
        }

        done.await(5, TimeUnit.SECONDS);
        assertThat(actionRun.get()).isEqualTo(2);  // action ran TWICE (2 trips)!
    }

    // ═══ CountDownLatch: countdown from different threads ═══
    @Test
    void latch_differentThreadsCountDown() throws InterruptedException {
        CountDownLatch latch = new CountDownLatch(2);

        new Thread(() -> { latch.countDown(); }).start();  // thread A counts
        new Thread(() -> { latch.countDown(); }).start();  // thread B counts

        latch.await(5, TimeUnit.SECONDS);  // MAIN thread waits!
        assertThat(latch.getCount()).isEqualTo(0);
        // Counting threads (A, B) ≠ waiting thread (main)!
    }
}
